/** Bounded, untrusted reference generated by gazeDesktopInstruction. */
export interface GazeExecutionReference {
  objectBounds: { x: number; y: number; width: number; height: number };
  displayBounds: { x: number; y: number; width: number; height: number };
  observedAt: number;
}
export function gazeExecutionReference(
  instruction: string,
  now = Date.now(),
): GazeExecutionReference | undefined {
  const line = instruction
    .split('\n')
    .find((line) => line.startsWith('[已绑定注视对象]'));
  if (!line) return undefined;
  try {
    const ref = JSON.parse(
      line.slice(line.indexOf('{')),
    ) as GazeExecutionReference;
    for (const bounds of [ref.objectBounds, ref.displayBounds]) {
      if (
        !bounds ||
        !Object.values(bounds).every(Number.isFinite) ||
        bounds.width <= 0 ||
        bounds.height <= 0
      )
        throw new Error();
    }
    if (
      !Number.isFinite(ref.observedAt) ||
      now - ref.observedAt > 120_000 ||
      ref.observedAt - now > 3000
    )
      throw new Error();
    return ref;
  } catch {
    throw new Error('注视对象的定位已过期或无效，请重新看向目标再操作。');
  }
}
export function gazeExecutionRect(
  ref: GazeExecutionReference,
  width: number,
  height: number,
) {
  const b = ref.objectBounds,
    d = ref.displayBounds;
  const x = Math.max(0, Math.round(((b.x - d.x) / d.width) * width));
  const y = Math.max(0, Math.round(((b.y - d.y) / d.height) * height));
  const right = Math.min(
    width,
    Math.round(((b.x + b.width - d.x) / d.width) * width),
  );
  const bottom = Math.min(
    height,
    Math.round(((b.y + b.height - d.y) / d.height) * height),
  );
  if (right <= x || bottom <= y)
    throw new Error('注视对象已不在当前屏幕，请重新锁定目标。');
  return { x, y, width: right - x, height: bottom - y };
}
export function assertGazeClick(
  ref: GazeExecutionReference,
  box: string,
  width: number,
  height: number,
) {
  const [x1, y1, x2 = x1, y2 = y1] = JSON.parse(box) as number[];
  const x = ((x1 + x2) / 2) * width,
    y = ((y1 + y2) / 2) * height;
  const r = gazeExecutionRect(ref, width, height);
  if (
    ![x, y].every(Number.isFinite) ||
    x < r.x ||
    x > r.x + r.width ||
    y < r.y ||
    y > r.y + r.height
  )
    throw new Error(
      '模型给出的首次点击超出了绑定的注视对象，已阻止点击。请重新锁定正确目标。',
    );
}

